import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { BrowserRouter as Router, Routes, Route, Link, useLocation } from 'react-router-dom';

// --- NAVBAR: With Active Underline & Orange Login ---
const Navbar = ({ cartCount }) => {
  const location = useLocation();

  // Fonction bach n-checkiw wach l-lien active
  const isActive = (path) => location.pathname === path;

  return (
    <nav className="bg-white/95 backdrop-blur-md sticky top-0 z-50 w-full border-b border-gray-100 shadow-sm">
      <div className="max-w-7xl mx-auto px-6 h-20 flex justify-between items-center">
        <Link to="/" className="flex items-center space-x-3">
          <div className="bg-orange-600 p-2 rounded-full shadow-md flex items-center justify-center">
            <svg width="24" height="24" viewBox="0 0 512 512" fill="white" xmlns="http://www.w3.org/2000/svg">
              <path d="M416 0c-35.3 0-64 28.7-64 64V288c0 17.7 14.3 32 32 32h32V480c0 17.7 14.3 32 32 32s32-14.3 32-32V32C480 14.3 465.7 0 448 0H416zM80 0C44.7 0 16 28.7 16 64V224c0 35.3 28.7 64 64 64h16V480c0 17.7 14.3 32 32 32s32-14.3 32-32V288h16c35.3 0 64-28.7 64-64V64c0-35.3-28.7-64-64-64H80zM128 0V192c0 8.8-7.2 16-16 16s-16-7.2-16-16V0H80V192c0 8.8-7.2 16-16 16s-16-7.2-16-16V0H16V192c0 53 43 96 96 96v192c0 17.7 14.3 32 32 32s32-14.3 32-32V288c53 0 96-43 96-96V0H224V192c0 8.8-7.2 16-16 16s-16-7.2-16-16V0H160V192c0 8.8-7.2 16-16 16s-16-7.2-16-16V0H128z" />
            </svg>
          </div>
          <span className="font-black text-xl tracking-tighter text-gray-900 uppercase italic">Fast<span className="text-orange-600">Délice</span></span>
        </Link>

        {/* Links with Orange Underline when Active */}
        <div className="hidden md:flex space-x-8 text-[12px] font-black uppercase text-gray-800">
          {[
            { name: 'Accueil', path: '/' },
            { name: 'Menu', path: '/menu' },
            { name: 'À Propos', path: '/about' },
            { name: 'Contact', path: '/contact' },
          ].map((link) => (
            <Link 
              key={link.path}
              to={link.path} 
              className={`relative pb-1 transition-all duration-300 hover:text-orange-600 ${isActive(link.path) ? 'text-orange-600' : ''}`}
            >
              {link.name}
              {isActive(link.path) && (
                <span className="absolute bottom-0 left-0 w-full h-0.5 bg-orange-600 rounded-full animate-pulse"></span>
              )}
            </Link>
          ))}
        </div>

        <div className="flex items-center space-x-6">
          <Link to="/panier" className="relative flex items-center space-x-2 text-gray-800 hover:text-orange-600 transition">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 3h2l.4 2M7 13h10l4-8H5.4M7 13L5.4 5M7 13l-2.293 2.293c-.63.63-.184 1.707.707 1.707H17m0 0a2 2 0 100 4 2 2 0 000-4zm-8 2a2 2 0 11-4 0 2 2 0 014 0z" />
            </svg>
            <span className="bg-orange-600 text-white text-[10px] font-bold rounded-full h-5 w-5 flex items-center justify-center">{cartCount}</span>
          </Link>
          {/* Connexion Button: Color Limoni (Orange) */}
          <Link to="/login" className="bg-orange-600 text-white px-6 py-2.5 rounded-full text-[11px] font-black uppercase tracking-widest hover:bg-gray-900 transition shadow-lg shadow-orange-600/20">
            Connexion
          </Link>
        </div>
      </div>
    </nav>
  );
};

// --- CONTACT PAGE: Rigeltha bach tji nqiya ---
const Contact = () => (
  <PageLayout title="Contactez-Nous">
    <div className="max-w-4xl mx-auto grid grid-cols-1 md:grid-cols-2 gap-10">
      <div className="bg-white/10 backdrop-blur-xl border border-white/20 p-10 rounded-[3rem] shadow-2xl">
        <h3 className="text-2xl font-black text-orange-600 italic mb-6 uppercase">Infos</h3>
        <div className="space-y-6">
          <div>
            <p className="text-orange-500 font-black text-[10px] uppercase tracking-widest">Adresse</p>
            <p className="text-white font-medium italic">123 Rue de la Gastronomie, Casablanca</p>
          </div>
          <div>
            <p className="text-orange-500 font-black text-[10px] uppercase tracking-widest">Téléphone</p>
            <p className="text-white font-medium italic">+212 5 22 00 00 00</p>
          </div>
          <div>
            <p className="text-orange-500 font-black text-[10px] uppercase tracking-widest">Email</p>
            <p className="text-white font-medium italic">hello@fastdelice.ma</p>
          </div>
        </div>
      </div>
      <form className="bg-black/40 backdrop-blur-xl border border-white/10 p-10 rounded-[3rem] space-y-4 shadow-2xl">
        <input type="text" placeholder="VOTRE NOM" className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-6 text-white outline-none focus:border-orange-600 transition text-xs font-bold uppercase tracking-widest" />
        <input type="email" placeholder="VOTRE EMAIL" className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-6 text-white outline-none focus:border-orange-600 transition text-xs font-bold uppercase tracking-widest" />
        <textarea placeholder="VOTRE MESSAGE" rows="4" className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-6 text-white outline-none focus:border-orange-600 transition text-xs font-bold uppercase tracking-widest"></textarea>
        <button className="w-full bg-orange-600 text-white py-5 rounded-2xl font-black uppercase tracking-widest hover:bg-white hover:text-black transition shadow-lg">Envoyer le message</button>
      </form>
    </div>
  </PageLayout>
);

// --- LOGIN PAGE: Rejje3na l-bouton limoni ---
const Login = () => (
  <PageLayout title="Connexion">
    <div className="max-w-md mx-auto bg-white/10 backdrop-blur-2xl border border-white/20 p-12 rounded-[3.5rem] shadow-2xl">
      <form className="space-y-8">
        <div>
          <label className="block text-white font-black text-[10px] uppercase tracking-widest mb-3">Email</label>
          <input type="email" placeholder="votre@email.com" className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-6 text-white outline-none focus:border-orange-600 transition font-bold" />
        </div>
        <div>
          <label className="block text-white font-black text-[10px] uppercase tracking-widest mb-3">Mot de passe</label>
          <input type="password" placeholder="••••••••" className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-6 text-white outline-none focus:border-orange-600 transition font-bold" />
        </div>
        <button className="w-full bg-orange-600 text-white py-5 rounded-2xl font-black uppercase tracking-widest hover:bg-white hover:text-black transition shadow-lg">Se Connecter</button>
      </form>
    </div>
  </PageLayout>
);

// --- REST OF COMPONENTS (Stay the same) ---
const OrderModal = ({ isOpen, onClose, onConfirm, itemName }) => {
  if (!isOpen) return null;
  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/70 backdrop-blur-md p-4">
      <div className="bg-white rounded-[3rem] p-10 max-w-sm w-full text-center shadow-2xl">
        <h3 className="text-2xl font-black text-gray-900 italic uppercase mb-2">Mode de Commande</h3>
        <p className="text-orange-600 font-bold mb-8 text-xs tracking-widest uppercase">{itemName}</p>
        <div className="space-y-4">
          <button onClick={() => onConfirm('Sur Place')} className="w-full py-4 bg-gray-100 hover:bg-orange-600 hover:text-white text-gray-900 rounded-2xl font-black uppercase tracking-widest transition-all">🍽️ Sur Place</button>
          <button onClick={() => onConfirm('À Emporter')} className="w-full py-4 bg-gray-900 text-white rounded-2xl font-black uppercase tracking-widest hover:bg-orange-600 transition-all">🛍️ À Emporter</button>
        </div>
        <button onClick={onClose} className="mt-6 text-gray-400 font-bold text-[10px] uppercase tracking-widest hover:text-red-500 transition">Annuler</button>
      </div>
    </div>
  );
};

const PageLayout = ({ children, title }) => (
  <div className="relative min-h-screen">
    <div className="fixed inset-0 z-0">
      <img src="https://images.unsplash.com/photo-1513104890138-7c749659a591?q=80&w=2070" className="w-full h-full object-cover" alt="bg" />
      <div className="absolute inset-0 bg-black/50 backdrop-blur-[4px]"></div>
    </div>
    <div className="relative z-10 max-w-7xl mx-auto px-6 py-16">
      {title && (
        <div className="text-center mb-16">
          <h2 className="text-5xl md:text-7xl font-black text-white italic tracking-tighter uppercase drop-shadow-2xl">{title}</h2>
          <div className="h-1.5 w-20 bg-orange-600 mx-auto mt-4 rounded-full"></div>
        </div>
      )}
      {children}
    </div>
  </div>
);

const Home = () => (
  <PageLayout>
    <div className="text-center py-16">
      <h1 className="text-7xl md:text-9xl font-black text-white mb-6 tracking-tighter italic drop-shadow-2xl leading-none">Fast<span className="text-orange-600">Délice</span></h1>
      <p className="text-xl text-white mb-12 font-black italic max-w-xl mx-auto opacity-90">"La passion du goût, l'élégance du service."</p>
      <Link to="/menu" className="bg-orange-600 text-white px-14 py-5 rounded-full font-black uppercase text-sm tracking-widest hover:bg-white hover:text-orange-600 transition shadow-2xl inline-block">Commander Maintenant</Link>

      <div className="mt-40 grid grid-cols-1 md:grid-cols-3 gap-8 text-center">
        {[
          {n: "YOUSSEF", t: "Meilleure pizza Margherita de la ville!"},
          {n: "SANAA", t: "Service ultra rapide et emballage top."},
          {n: "KARIM", t: "Les saveurs sont vraiment authentiques."}
        ].map((v, i) => (
          <div key={i} className="bg-white/10 backdrop-blur-xl p-10 rounded-[3rem] border border-white/20 hover:bg-white/20 transition-all duration-500">
             <div className="text-orange-500 mb-4 text-xs tracking-widest">★★★★★</div>
             <p className="text-white italic font-bold mb-6">"{v.t}"</p>
             <span className="text-[10px] font-black text-orange-500 uppercase tracking-widest">— {v.n}</span>
          </div>
        ))}
      </div>
    </div>
  </PageLayout>
);

const Menu = ({ categories, addToCart }) => {
  const [selectedItem, setSelectedItem] = useState(null);
  return (
    <PageLayout title="La Carte">
      <div className="grid grid-cols-1 md:grid-cols-3 gap-10">
        {categories.flatMap(c => c.dishes).map(item => (
          <div key={item.id} className="bg-black/40 backdrop-blur-lg border border-white/10 rounded-[3rem] overflow-hidden group">
            <div className="h-64 overflow-hidden relative">
              <img src={item.image || "https://images.unsplash.com/photo-1513104890138-7c749659a591?q=80&w=1000"} alt={item.name} className="w-full h-full object-cover group-hover:scale-110 transition duration-700" />
            </div>
            <div className="p-8 text-center">
              <h3 className="text-2xl font-black text-white italic mb-2 uppercase">{item.name}</h3>
              <p className="text-orange-500 font-black text-2xl mb-6">{item.price} DH</p>
              <button onClick={() => setSelectedItem(item)} className="w-full py-4 bg-white text-black rounded-2xl font-black uppercase text-[10px] tracking-widest hover:bg-orange-600 hover:text-white transition">Commander</button>
            </div>
          </div>
        ))}
      </div>
      <OrderModal isOpen={!!selectedItem} onClose={() => setSelectedItem(null)} onConfirm={(type) => { addToCart({...selectedItem, type}); setSelectedItem(null); }} itemName={selectedItem?.name} />
    </PageLayout>
  );
};

const About = () => (
  <PageLayout title="À Propos">
    <div className="max-w-5xl mx-auto space-y-10">
      <div className="bg-white/10 backdrop-blur-xl border border-white/20 p-12 rounded-[3.5rem] shadow-2xl">
        <h3 className="text-4xl font-black text-orange-600 italic mb-8 uppercase text-center">Notre Histoire</h3>
        <p className="text-white text-lg leading-relaxed font-medium italic opacity-90 text-center">
          FastDélice est né de la volonté d'offrir une cuisine de chef avec la rapidité du service moderne. 
          Chaque ingrédient est choisi avec soin pour garantir une explosion de saveurs à chaque bouchée. 
          Nous croyons que la qualité ne doit jamais être sacrifiée pour la vitesse.
        </p>
      </div>
    </div>
  </PageLayout>
);

const Panier = ({ cart }) => (
  <PageLayout title="Panier">
    <div className="max-w-2xl mx-auto bg-white/10 backdrop-blur-2xl border border-white/20 p-12 rounded-[3.5rem]">
      {cart.length === 0 ? (
        <p className="text-white text-center italic opacity-60">Panier vide.</p>
      ) : (
        <div className="space-y-6">
          {cart.map((item, i) => (
            <div key={i} className="flex justify-between items-center text-white border-b border-white/10 pb-4">
              <div><p className="font-black italic uppercase">{item.name}</p><span className="text-orange-500 text-xs">{item.type}</span></div>
              <span className="font-bold">{item.price} DH</span>
            </div>
          ))}
          <button className="w-full mt-8 bg-orange-600 text-white py-5 rounded-2xl font-black uppercase">Confirmer</button>
        </div>
      )}
    </div>
  </PageLayout>
);

export default function App() {
  const [categories, setCategories] = useState([]);
  const [cart, setCart] = useState([]);

  useEffect(() => {
    axios.get('http://127.0.0.1:8000/api/categories/').then(res => setCategories(res.data)).catch(e => console.log(e));
  }, []);

  return (
    <Router>
      <div className="min-h-screen bg-black">
        <Navbar cartCount={cart.length} />
        <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/menu" element={<Menu categories={categories} addToCart={(i) => setCart([...cart, i])} />} />
          <Route path="/about" element={<About />} />
          <Route path="/contact" element={<Contact />} />
          <Route path="/login" element={<Login />} />
          <Route path="/panier" element={<Panier cart={cart} />} />
        </Routes>
      </div>
    </Router>
  );
}
